import { icon } from '../../core/icon.2e5a22ae4d4e.mjs';
import { t } from '../../core/i18n.84a64209dc8e.mjs';
export function buildProjectViewModel({ id, path, name = null, trust = 'unknown', missions = [], defaultProvider = 'auto', defaultMode = 'balanced', rulesSummary = null } = {}) {
  if (!id || !path) throw new Error('Project view requires id and path');
  const active = new Set(['planning', 'running', 'needs-input', 'needs_input', 'reviewing','testing']);
  return Object.freeze({ id: String(id), path: String(path), name:name??String(path).split(/[\\/]/).filter(Boolean).at(-1)??String(id), trust: String(trust), activeMissions: missions.filter((mission) => active.has(mission.status)).length, completedMissions: missions.filter((mission) => mission.status === 'completed').length, defaultProvider, defaultMode, rulesSummary, openIntelligenceRoute: `/control-plane/intelligence/repository?project=${encodeURIComponent(id)}` });
}
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderProjectView(value) { return renderProjectsView({projects:[value],language:'en'}); }
export function createProjectsController({api,language='en'}={}){let state={status:'loading',language,projects:[],missions:[],error:null,query:''};const snapshot=()=>structuredClone(state);return Object.freeze({snapshot,async load(){state.status='loading';const r=await Promise.allSettled([api.get('/api/projects'),api.get('/api/missions')]);const p=r[0].status==='fulfilled'?(Array.isArray(r[0].value)?r[0].value:r[0].value?.projects??[]):[];const m=r[1].status==='fulfilled'?(Array.isArray(r[1].value)?r[1].value:r[1].value?.missions??[]):[];state={...state,status:'ready',projects:p.map(project=>buildProjectViewModel({...project,path:project.path??project.root??project.id,missions:m.filter(x=>String(x.projectId)===String(project.id))})),missions:m,error:r.every(x=>x.status==='rejected')?'Nolane runtime could not be reached.':null};return snapshot()},setQuery(query){state.query=String(query??'');return snapshot()}})}
function trustTone(trust){return trust==='trusted'?'success':trust==='blocked'?'danger':'warning'}
export function renderProjectsView(state={}){const lang=state.language??'en';const q=String(state.query??'').toLowerCase();const projects=(state.projects??[]).filter(p=>!q||`${p.name} ${p.path} ${p.id}`.toLowerCase().includes(q));return `<section class="surface-page projects-page"><header class="surface-page__header"><div><p class="eyebrow">${lang==='vi'?'Danh mục workspace':'Workspace registry'}</p><h1>${t('projects.title',lang)}</h1><p>${t('projects.subtitle',lang)}</p></div><button type="button" class="surface-primary" data-project-action="add">${icon('plus',{size:16})}<span>${lang==='vi'?'Thêm dự án':'Add project'}</span></button></header><div class="surface-toolbar"><label class="surface-search">${icon('search',{size:15})}<input type="search" data-project-search placeholder="${lang==='vi'?'Tìm dự án…':'Search projects…'}" value="${esc(state.query??'')}"></label><div class="surface-view-toggle"><button type="button" aria-pressed="true" aria-label="${lang==='vi'?'Chế độ lưới dự án':'Project grid view'}">${icon('projects',{size:15})}</button><button type="button" aria-pressed="false" aria-label="${lang==='vi'?'Chế độ hoạt động dự án':'Project activity view'}">${icon('activity',{size:15})}</button></div></div>${state.status==='loading'?`<div class="page-loading"><span class="spinner"></span>${t('common.loading',lang)}</div>`:state.error?`<div class="page-error">${icon('warning',{size:18})}<span>${esc(state.error)}</span></div>`:projects.length?`<div class="project-grid">${projects.map(p=>`<article class="project-card" data-project-id="${esc(p.id)}"><header><span class="project-card__mark">${icon('projects',{size:19})}</span><div><h2>${esc(p.name)}</h2><code>${esc(p.path)}</code></div><button type="button" aria-label="${lang==='vi'?'Tùy chọn dự án':'Project options'}">•••</button></header><div class="project-card__metrics"><span><strong>${p.activeMissions}</strong><small>${lang==='vi'?'đang chạy':'active'}</small></span><span><strong>${p.completedMissions}</strong><small>${lang==='vi'?'hoàn tất':'completed'}</small></span><span><i data-tone="${trustTone(p.trust)}"></i><small>${esc(p.trust)}</small></span></div><footer><a href="#/?project=${encodeURIComponent(p.id)}" data-route="/?project=${encodeURIComponent(p.id)}">${icon('chat',{size:15})}${t('projects.open',lang)}</a><a href="#${esc(p.openIntelligenceRoute)}" data-route="${esc(p.openIntelligenceRoute)}">${icon('control',{size:15})}${t('projects.intelligence',lang)}</a></footer></article>`).join('')}</div>`:`<div class="empty-state page-empty"><span>${icon('projects',{size:20})}</span><strong>${lang==='vi'?'Chưa có dự án':'No projects yet'}</strong><p>${t('projects.empty',lang)}</p></div>`}</section>`}
